class ExaAIService:
    """Exa AI keresési szolgáltatás integráció a NeuMeta LLM-hez"""
    def __init__(self):
        self.api_key = os.getenv('EXA_API_KEY')
        self.exa = None

        # Sándor Kollár digitális aláírás
        self.signature = "🔑 Created by Sándor Kollár with ❤️ - Premium Exa AI Integration"

        if EXA_AVAILABLE and self.api_key:
            self._initialize_exa()
        else:
            print("⚠️ Exa AI API kulcs nem található a Secrets-ben")

    def _initialize_exa(self):
        """Exa AI kliens inicializálása"""
        try:
            self.exa = exa_py.Exa(api_key=self.api_key)
            print("✅ Exa AI sikeresen inicializálva!")
            print(f"🔑 {self.signature}")
        except Exception as e:
            print(f"❌ Exa AI inicializálási hiba: {e}")

    def search_and_enhance(self, query: str, num_results: int = 5) -> Dict[str, any]:
        """Keresés és kontextus bővítés a NeuMeta modellhez"""
        if not self.exa:
            return {
                "enhanced_context": f"Offline mód: {query}",
                "sources": [],
                "error": "Exa AI nem elérhető"
            }

        try:
            # Exa keresés végrehajtása
            search_results = self.exa.search(
                query=query,
                num_results=num_results,
                include_domains=["wikipedia.org", "arxiv.org", "github.com"],
                use_autoprompt=True
            )

            # Tartalom lekérése
            content_results = self.exa.get_contents(
                ids=[result.id for result in search_results.results]
            )

            # Kontextus összeállítása
            enhanced_context = self._build_enhanced_context(query, content_results)

            return {
                "enhanced_context": enhanced_context,
                "sources": [
                    {
                        "title": result.title,
                        "url": result.url,
                        "score": result.score
                    }
                    for result in search_results.results
                ],
                "exa_signature": self.signature
            }

        except Exception as e:
            print(f"❌ Exa keresési hiba: {e}")
            return {
                "enhanced_context": f"Keresési hiba: {query}",
                "sources": [],
                "error": str(e)
            }

    def _build_enhanced_context(self, original_query: str, content_results) -> str:
        """Bővített kontextus összeállítása"""
        context_parts = [f"Eredeti kérdés: {original_query}\n"]
        context_parts.append("📚 Friss információk:")

        for i, content in enumerate(content_results.results[:3]):
            if content.text:
                # Rövidítés és tisztítás
                clean_text = content.text[:500].replace('\n', ' ').strip()
                context_parts.append(f"{i+1}. {clean_text}...")

        context_parts.append(f"\n🔑 {self.signature}")
        return "\n\n".join(context_parts)

    def intelligent_search(self, prompt: str, search_type: str = "semantic") -> str:
        """Intelligens keresés különböző típusokkal"""
        if not self.exa:
            return f"Offline mód: {prompt}"

        try:
            if search_type == "semantic":
                # Szemantikus keresés
                results = self.exa.search(
                    query=prompt,
                    type="neural",
                    num_results=3,
                    use_autoprompt=True
                )
            elif search_type == "keyword":
                # Kulcsszavas keresés
                results = self.exa.search(
                    query=prompt,
                    type="keyword",
                    num_results=3
                )
            else:
                # Hibrid keresés
                results = self.exa.search(
                    query=prompt,
                    num_results=3,
                    use_autoprompt=True
                )

            # Összegzés készítése
            if results.results:
                summary = f"🔍 Keresési eredmények '{prompt}' témában:\n"
                for i, result in enumerate(results.results):
                    summary += f"{i+1}. {result.title}\n   📊 Relevancia: {result.score:.2f}\n"
                return summary
            else:
                return f"Nem találtam releváns információt a témában: {prompt}"

        except Exception as e:
            return f"Keresési hiba: {e}"

